/** Points p_from … p_(from+count−1) of a key's series at the record's precision. `from` is the point's index in the precision's stream since the world began, mod 65,536: a whole series is the last min(300, n) points, an incremental one the points appended since the previous record (§15.5, B1-r1 15) */
export interface StatSeries {
  key: number;
  from: number;
  produced: number[];
  consumed: number[];
}
export const StatSeriesCodec = {
  /** The bytes before the first variable-length field. */
  PREFIX: 8,
  /** Byte offsets of the fields in the fixed prefix. */
  OFFSET: { key: 0, from: 4, count: 6 },
  /** A value with every field at its default (optional fields absent). */
  defaults(): StatSeries {
    return { key: 0, from: 0, produced: [], consumed: [] };
  },
  /** Field reads at byte offset `o` of a DataView (no validation: for records already validated). */
  get: {
    key: (v: DataView, o: number): number => v.getUint32(o + 0, true),
    from: (v: DataView, o: number): number => v.getUint16(o + 4, true),
    count: (v: DataView, o: number): number => v.getUint16(o + 6, true),
  },
  read(r: Reader): StatSeries {
    
    const f_key = StatKeyCodec.read(r, "StatSeries.key");
    const f_from = r.u16("StatSeries.from");
    const at_count = r.pos;
    const f_count = r.u16("StatSeries.count");
    if (f_count < 0 || f_count > 300) throw r.errAt(at_count, 'range', "StatSeries.count");
    const f_produced = readN(r, f_count, 4, "StatSeries.produced", () => r.f32("StatSeries.produced"));
    const f_consumed = readN(r, f_count, 4, "StatSeries.consumed", () => r.f32("StatSeries.consumed"));
    
    return { key: f_key, from: f_from, produced: f_produced, consumed: f_consumed };
  },
  write(w: Writer, v: StatSeries): void {
    
    const f_count = v.produced.length;
    if (f_count > 300) throw new EncodeError('range', "StatSeries.count");
    if (v.consumed.length !== f_count) throw new EncodeError('bad_count', "StatSeries.consumed");
    StatKeyCodec.write(w, v.key, "StatSeries.key");
    w.u16(v.from, "StatSeries.from");
    w.u16(f_count, "StatSeries.count");
    for (const x of v.produced) { w.f32(x, "StatSeries.produced"); }
    for (const x of v.consumed) { w.f32(x, "StatSeries.consumed"); }
    
  },
  /** Decodes one value that fills `bytes` exactly. */
  decode(bytes: Uint8Array): StatSeries {
    const r = new Reader(bytes);
    const v = StatSeriesCodec.read(r);
    r.finish("StatSeries");
    return v;
  },
  /** Encodes one value. */
  encode(v: StatSeries): Uint8Array {
    const w = new Writer();
    StatSeriesCodec.write(w, v);
    return w.finish();
  },
  dump(d: Dump, v: StatSeries, prefix = ''): void {
    d.int(`${prefix}key`, v.key);
    d.int(`${prefix}from`, v.from);
    d.int(`${`${prefix}produced`}.len`, v.produced.length); v.produced.forEach((x, i) => { d.f32(`${`${prefix}produced`}[${i}]`, x); });
    d.int(`${`${prefix}consumed`}.len`, v.consumed.length); v.consumed.forEach((x, i) => { d.f32(`${`${prefix}consumed`}[${i}]`, x); });
  },
};

/** sim_state_hash's output and the `hash` query's result (§15.8): the full state hash, then each section's (low word first) */
export interface StateHash {
  hash: bigint;
  sections: SectionHash[];
}
export const StateHashCodec = {
  /** The bytes before the first variable-length field. */
  PREFIX: 12,
  /** Byte offsets of the fields in the fixed prefix. */
  OFFSET: { hash: 0, count: 8 },
  /** A value with every field at its default (optional fields absent). */
  defaults(): StateHash {
    return { hash: 0n, sections: [] };
  },
  /** Field reads at byte offset `o` of a DataView (no validation: for records already validated). */
  get: {
    hash: (v: DataView, o: number): bigint => v.getBigUint64(o + 0, true),
    count: (v: DataView, o: number): number => v.getUint32(o + 8, true),
  },
  read(r: Reader): StateHash {
    
    const f_hash = r.u64("StateHash.hash");
    const f_count = r.u32("StateHash.count");
    const f_sections = readN(r, f_count, 12, "StateHash.sections", () => SectionHashCodec.read(r, "StateHash.sections"));
    
    return { hash: f_hash, sections: f_sections };
  },
  write(w: Writer, v: StateHash): void {
    
    const f_count = v.sections.length;
    if (f_count > 4294967295) throw new EncodeError('bad_count', "StateHash.count");
    w.u64(v.hash, "StateHash.hash");
    w.u32(f_count, "StateHash.count");
    for (const x of v.sections) { SectionHashCodec.write(w, x, "StateHash.sections"); }
    
  },
  /** Decodes one value that fills `bytes` exactly. */
  decode(bytes: Uint8Array): StateHash {
    const r = new Reader(bytes);
    const v = StateHashCodec.read(r);
    r.finish("StateHash");
    return v;
  },
  /** Encodes one value. */
  encode(v: StateHash): Uint8Array {
    const w = new Writer();
    StateHashCodec.write(w, v);
    return w.finish();
  },
  dump(d: Dump, v: StateHash, prefix = ''): void {
    d.int(`${prefix}hash`, v.hash);
    d.int(`${`${prefix}sections`}.len`, v.sections.length); v.sections.forEach((x, i) => { SectionHashCodec.dump(d, x, `${`${`${prefix}sections`}[${i}]`}.`); });
  },
};

export interface Stats {
  precision: number;
  tab: number;
  flags: number;
  entries: StatEntry[];
  series: StatSeries[];
}
export const StatsCodec = {
  /** The bytes before the first variable-length field. */
  PREFIX: 4,
  /** Byte offsets of the fields in the fixed prefix. */
  OFFSET: { precision: 0, tab: 1, flags: 2 },
  /** A value with every field at its default (optional fields absent). */
  defaults(): Stats {
    return { precision: 0, tab: 0, flags: 0, entries: [], series: [] };
  },
  /** Field reads at byte offset `o` of a DataView (no validation: for records already validated). */
  get: {
    precision: (v: DataView, o: number): number => v.getUint8(o + 0),
    tab: (v: DataView, o: number): number => v.getUint8(o + 1),
    flags: (v: DataView, o: number): number => v.getUint8(o + 2),
  },
  read(r: Reader): Stats {
    
    const f_precision = StatPrecisionCodec.read(r, "Stats.precision");
    const f_tab = StatTabCodec.read(r, "Stats.tab");
    const f_flags = StatsFlagsCodec.read(r, "Stats.flags");
    r.zeros(1, "Stats.reserved");
    const f_entries = readList(r, 2, 256, "Stats.entries", 20, () => StatEntryCodec.read(r, "Stats.entries"));
    const f_series = readList(r, 2, 24, "Stats.series", 0, () => StatSeriesCodec.read(r));
    
    return { precision: f_precision, tab: f_tab, flags: f_flags, entries: f_entries, series: f_series };
  },
  write(w: Writer, v: Stats): void {
    
    StatPrecisionCodec.write(w, v.precision, "Stats.precision");
    StatTabCodec.write(w, v.tab, "Stats.tab");
    StatsFlagsCodec.write(w, v.flags, "Stats.flags");
    w.zeros(1);
    w.count(v.entries.length, 2, 256, "Stats.entries"); for (const x of v.entries) { StatEntryCodec.write(w, x, "Stats.entries"); }
    w.count(v.series.length, 2, 24, "Stats.series"); for (const x of v.series) { StatSeriesCodec.write(w, x); }
    
  },
  /** Decodes one value that fills `bytes` exactly. */
  decode(bytes: Uint8Array): Stats {
    const r = new Reader(bytes);
    const v = StatsCodec.read(r);
    r.finish("Stats");
    return v;
  },
  /** Encodes one value. */
  encode(v: Stats): Uint8Array {
    const w = new Writer();
    StatsCodec.write(w, v);
    return w.finish();
  },
  dump(d: Dump, v: Stats, prefix = ''): void {
    d.int(`${prefix}precision`, v.precision);
    d.int(`${prefix}tab`, v.tab);
    d.int(`${prefix}flags`, v.flags);
    d.int(`${`${prefix}entries`}.len`, v.entries.length); v.entries.forEach((x, i) => { StatEntryCodec.dump(d, x, `${`${`${prefix}entries`}[${i}]`}.`); });
    d.int(`${`${prefix}series`}.len`, v.series.length); v.series.forEach((x, i) => { StatSeriesCodec.dump(d, x, `${`${`${prefix}series`}[${i}]`}.`); });
  },
};

