/** A subscription request (§15.5): main → shell → sim_subscribe. Sending an existing sub_id replaces it */
export interface SubRequest {
  sub_id: number;
  kind: number;
  flags: number;
  /** an entity serial, a player index or 0, by kind */
  target: number;
  p0: number;
  p1: number;
  p2: number;
  p3: number;
  /** list parameters (STATS: up to 256 u32 StatKeys) */
  tail?: Uint8Array;
}
export const SubRequestCodec = {
  /** The bytes before the first variable-length field. */
  PREFIX: 28,
  /** Byte offsets of the fields in the fixed prefix. */
  OFFSET: { sub_id: 0, kind: 4, flags: 6, target: 8, p0: 12, p1: 16, p2: 20, p3: 24 },
  /** A value with every field at its default (optional fields absent). */
  defaults(): SubRequest {
    return { sub_id: 0, kind: 1, flags: 0, target: 0, p0: 0, p1: 0, p2: 0, p3: 0 };
  },
  /** Field reads at byte offset `o` of a DataView (no validation: for records already validated). */
  get: {
    sub_id: (v: DataView, o: number): number => v.getUint32(o + 0, true),
    kind: (v: DataView, o: number): number => v.getUint16(o + 4, true),
    flags: (v: DataView, o: number): number => v.getUint16(o + 6, true),
    target: (v: DataView, o: number): number => v.getUint32(o + 8, true),
    p0: (v: DataView, o: number): number => v.getUint32(o + 12, true),
    p1: (v: DataView, o: number): number => v.getUint32(o + 16, true),
    p2: (v: DataView, o: number): number => v.getUint32(o + 20, true),
    p3: (v: DataView, o: number): number => v.getUint32(o + 24, true),
  },
  read(r: Reader): SubRequest {
    
    const f_sub_id = SubIdCodec.read(r, "SubRequest.sub_id");
    const f_kind = ProjectionKindCodec.read(r, "SubRequest.kind");
    const f_flags = SubFlagsCodec.read(r, "SubRequest.flags");
    const f_target = r.u32("SubRequest.target");
    const f_p0 = r.u32("SubRequest.p0");
    const f_p1 = r.u32("SubRequest.p1");
    const f_p2 = r.u32("SubRequest.p2");
    const f_p3 = r.u32("SubRequest.p3");
    const f_tail = (f_flags & SubFlags.tail) !== 0 ? r.bytesOf(2, 4096, "SubRequest.tail").slice() : undefined;
    
    return { sub_id: f_sub_id, kind: f_kind, flags: f_flags, target: f_target, p0: f_p0, p1: f_p1, p2: f_p2, p3: f_p3, ...(f_tail !== undefined ? { tail: f_tail } : {}) };
  },
  write(w: Writer, v: SubRequest): void {
    
    SubIdCodec.write(w, v.sub_id, "SubRequest.sub_id");
    ProjectionKindCodec.write(w, v.kind, "SubRequest.kind");
    SubFlagsCodec.write(w, v.flags, "SubRequest.flags");
    w.u32(v.target, "SubRequest.target");
    w.u32(v.p0, "SubRequest.p0");
    w.u32(v.p1, "SubRequest.p1");
    w.u32(v.p2, "SubRequest.p2");
    w.u32(v.p3, "SubRequest.p3");
    if (((v.flags & SubFlags.tail) !== 0) !== (v.tail !== undefined)) throw new EncodeError('inconsistent', "SubRequest.tail");
    if (v.tail !== undefined) { w.lenBytes(v.tail, 2, 4096, "SubRequest.tail"); }
    
  },
  /** Decodes one value that fills `bytes` exactly. */
  decode(bytes: Uint8Array): SubRequest {
    const r = new Reader(bytes);
    const v = SubRequestCodec.read(r);
    r.finish("SubRequest");
    return v;
  },
  /** Encodes one value. */
  encode(v: SubRequest): Uint8Array {
    const w = new Writer();
    SubRequestCodec.write(w, v);
    return w.finish();
  },
  dump(d: Dump, v: SubRequest, prefix = ''): void {
    d.int(`${prefix}sub_id`, v.sub_id);
    d.int(`${prefix}kind`, v.kind);
    d.int(`${prefix}flags`, v.flags);
    d.int(`${prefix}target`, v.target);
    d.int(`${prefix}p0`, v.p0);
    d.int(`${prefix}p1`, v.p1);
    d.int(`${prefix}p2`, v.p2);
    d.int(`${prefix}p3`, v.p3);
    if (v.tail !== undefined) { d.bytes(`${prefix}tail`, v.tail); }
  },
};

/** Developer reasons without player-facing text (§15.5); the shell logs them. Also the body of a failed query */
export const UiInvalidReason = {
  unsupported: 1,
  bad_parameters: 2,
  over_limit: 3,
  not_found: 4,
} as const;
export type UiInvalidReason = number;
const UiInvalidReason_NAMES: ReadonlyMap<number, string> = new Map([[1, "unsupported"], [2, "bad_parameters"], [3, "over_limit"], [4, "not_found"]]);
export const UiInvalidReasonCodec = {
  SIZE: 2,
  /** Every value, in declaration order. */
  ALL: [1, 2, 3, 4] as readonly number[],
  /** The schema's name of a value, or undefined. */
  name: (v: number): string | undefined => UiInvalidReason_NAMES.get(v),
  has: (v: number): boolean => UiInvalidReason_NAMES.has(v),
  read(r: Reader, field: string): number {
    const at = r.pos;
    const v = r.u16(field);
    if (!UiInvalidReason_NAMES.has(v)) throw r.errAt(at, 'bad_enum', field);
    return v;
  },
  write(w: Writer, v: number, field: string): void {
    if (!UiInvalidReason_NAMES.has(v)) throw new EncodeError('bad_enum', field);
    w.u16(v, field);
  },
} as const;

/** One record of the UI section: the header, the kind's record (`len` bytes; a UiInvalidReason when status is 2), padding to 4 */
export interface UiRecord {
  sub_id: number;
  kind: number;
  status: number;
  version: number;
  body: Uint8Array;
}
export const UiRecordCodec = {
  /** The bytes before the first variable-length field. */
  PREFIX: 16,
  /** Byte offsets of the fields in the fixed prefix. */
  OFFSET: { sub_id: 0, kind: 4, status: 6, version: 8, len: 12 },
  /** A value with every field at its default (optional fields absent). */
  defaults(): UiRecord {
    return { sub_id: 0, kind: 1, status: 0, version: 0, body: new Uint8Array(0) };
  },
  /** Field reads at byte offset `o` of a DataView (no validation: for records already validated). */
  get: {
    sub_id: (v: DataView, o: number): number => v.getUint32(o + 0, true),
    kind: (v: DataView, o: number): number => v.getUint16(o + 4, true),
    status: (v: DataView, o: number): number => v.getUint16(o + 6, true),
    version: (v: DataView, o: number): number => v.getUint32(o + 8, true),
    len: (v: DataView, o: number): number => v.getUint32(o + 12, true),
  },
  read(r: Reader): UiRecord {
    const start = r.pos;
    const f_sub_id = SubIdCodec.read(r, "UiRecord.sub_id");
    const f_kind = ProjectionKindCodec.read(r, "UiRecord.kind");
    const f_status = UiStatusCodec.read(r, "UiRecord.status");
    const f_version = r.u32("UiRecord.version");
    const f_len = r.u32("UiRecord.len");
    const f_body = r.take(f_len, "UiRecord.body").slice();
    r.pad(start, 4, "UiRecord.padding");
    return { sub_id: f_sub_id, kind: f_kind, status: f_status, version: f_version, body: f_body };
  },
  write(w: Writer, v: UiRecord): void {
    const start = w.pos;
    const f_len = v.body.length;
    if (f_len > 4294967295) throw new EncodeError('bad_count', "UiRecord.len");
    SubIdCodec.write(w, v.sub_id, "UiRecord.sub_id");
    ProjectionKindCodec.write(w, v.kind, "UiRecord.kind");
    UiStatusCodec.write(w, v.status, "UiRecord.status");
    w.u32(v.version, "UiRecord.version");
    w.u32(f_len, "UiRecord.len");
    w.bytes(v.body);
    w.pad(start, 4);
  },
  /** Decodes one value that fills `bytes` exactly. */
  decode(bytes: Uint8Array): UiRecord {
    const r = new Reader(bytes);
    const v = UiRecordCodec.read(r);
    r.finish("UiRecord");
    return v;
  },
  /** Encodes one value. */
  encode(v: UiRecord): Uint8Array {
    const w = new Writer();
    UiRecordCodec.write(w, v);
    return w.finish();
  },
  dump(d: Dump, v: UiRecord, prefix = ''): void {
    d.int(`${prefix}sub_id`, v.sub_id);
    d.int(`${prefix}kind`, v.kind);
    d.int(`${prefix}status`, v.status);
    d.int(`${prefix}version`, v.version);
    d.bytes(`${prefix}body`, v.body);
  },
};

/** A UI record (16 bytes), then the kind's record (`len` bytes, padded to 4). A status-2 record's body is a UiInvalidReason */
export interface UiRecordHeader {
  sub_id: number;
  kind: number;
  status: number;
  /** counts the records sent for this subscription */
  version: number;
  len: number;
}
export const UiRecordHeaderCodec = {
  /** The encoded size in bytes. */
  SIZE: 16,
  /** Byte offsets of the fields. */
  OFFSET: { sub_id: 0, kind: 4, status: 6, version: 8, len: 12 },
  /** A value with every field at its default. */
  defaults(): UiRecordHeader {
    return { sub_id: 0, kind: 1, status: 0, version: 0, len: 0 };
  },
  /** Field reads at byte offset `o` of a DataView (no validation: for records already validated). */
  get: {
    sub_id: (v: DataView, o: number): number => v.getUint32(o + 0, true),
    kind: (v: DataView, o: number): number => v.getUint16(o + 4, true),
    status: (v: DataView, o: number): number => v.getUint16(o + 6, true),
    version: (v: DataView, o: number): number => v.getUint32(o + 8, true),
    len: (v: DataView, o: number): number => v.getUint32(o + 12, true),
  },
  read(r: Reader, _field?: string): UiRecordHeader {
    
    const f_sub_id = SubIdCodec.read(r, "UiRecordHeader.sub_id");
    const f_kind = ProjectionKindCodec.read(r, "UiRecordHeader.kind");
    const f_status = UiStatusCodec.read(r, "UiRecordHeader.status");
    const f_version = r.u32("UiRecordHeader.version");
    const f_len = r.u32("UiRecordHeader.len");
    const v: UiRecordHeader = { sub_id: f_sub_id, kind: f_kind, status: f_status, version: f_version, len: f_len };
    
    return v;
  },
  write(w: Writer, v: UiRecordHeader, _field?: string): void {
    
    SubIdCodec.write(w, v.sub_id, "UiRecordHeader.sub_id");
    ProjectionKindCodec.write(w, v.kind, "UiRecordHeader.kind");
    UiStatusCodec.write(w, v.status, "UiRecordHeader.status");
    w.u32(v.version, "UiRecordHeader.version");
    w.u32(v.len, "UiRecordHeader.len");
  },
  compare(a: UiRecordHeader, b: UiRecordHeader): number {
    { const c = cmpScalar(a.sub_id, b.sub_id); if (c !== 0) return c; }
    { const c = cmpScalar(a.kind, b.kind); if (c !== 0) return c; }
    { const c = cmpScalar(a.status, b.status); if (c !== 0) return c; }
    { const c = cmpScalar(a.version, b.version); if (c !== 0) return c; }
    { const c = cmpScalar(a.len, b.len); if (c !== 0) return c; }
    return 0;
  },
  dump(d: Dump, v: UiRecordHeader, prefix = ''): void {
    d.int(`${prefix}sub_id`, v.sub_id);
    d.int(`${prefix}kind`, v.kind);
    d.int(`${prefix}status`, v.status);
    d.int(`${prefix}version`, v.version);
    d.int(`${prefix}len`, v.len);
  },
};

export const UiStatus = {
  ok: 0,
  gone: 1,
  invalid: 2,
} as const;
export type UiStatus = number;
const UiStatus_NAMES: ReadonlyMap<number, string> = new Map([[0, "ok"], [1, "gone"], [2, "invalid"]]);
export const UiStatusCodec = {
  SIZE: 2,
  /** Every value, in declaration order. */
  ALL: [0, 1, 2] as readonly number[],
  /** The schema's name of a value, or undefined. */
  name: (v: number): string | undefined => UiStatus_NAMES.get(v),
  has: (v: number): boolean => UiStatus_NAMES.has(v),
  read(r: Reader, field: string): number {
    const at = r.pos;
    const v = r.u16(field);
    if (!UiStatus_NAMES.has(v)) throw r.errAt(at, 'bad_enum', field);
    return v;
  },
  write(w: Writer, v: number, field: string): void {
    if (!UiStatus_NAMES.has(v)) throw new EncodeError('bad_enum', field);
    w.u16(v, field);
  },
} as const;

/** Subscription and query limits (§15.5). */
export const QUERIES_RUNNING = 4;
export const QUERY_RESULT_MAX = 1048576;
export const QUERY_STEP_MS = 2;
export const RECORD_MAX = 65536;
export const SLOW_CADENCE_TICKS = 60;
export const STATS_KEYS = 256;
export const STATS_SERIES_KEYS = 24;
export const STATS_SUBSCRIPTIONS = 4;
export const SUBSCRIPTIONS = 32;
export const UI_SECTION_MAX = 262144;

