/** A decoded projection record, by kind name. */
export type Projection =
  | ({ kind: "HUD" } & Hud)
  | ({ kind: "CHARACTER" } & Character)
  | ({ kind: "INVENTORY" } & Inventory)
  | ({ kind: "ENTITY_PANEL" } & EntityPanel)
  | ({ kind: "HOVER" } & Hover)
  | ({ kind: "STATS" } & Stats)
  | ({ kind: "DEBUG" } & Debug);

/** Decodes the body of a UI record of kind id `kind` (status 0), which must fill `body` exactly. */
export function decodeProjection(kind: number, body: Uint8Array): Projection {
  const r = new Reader(body);
  let p: Projection;
  switch (kind) {
    case 1:
      p = { kind: "HUD", ...HudCodec.read(r) };
      break;
    case 2:
      p = { kind: "CHARACTER", ...CharacterCodec.read(r) };
      break;
    case 3:
      p = { kind: "INVENTORY", ...InventoryCodec.read(r) };
      break;
    case 4:
      p = { kind: "ENTITY_PANEL", ...EntityPanelCodec.read(r) };
      break;
    case 5:
      p = { kind: "HOVER", ...HoverCodec.read(r) };
      break;
    case 7:
      p = { kind: "STATS", ...StatsCodec.read(r) };
      break;
    case 10:
      p = { kind: "DEBUG", ...DebugCodec.read(r) };
      break;
    default:
      throw new DecodeError('unknown_type', 'UiRecord.kind', 0);
  }
  r.finish('UiRecord.body');
  return p;
}

/** Encodes a projection record's body. */
export function encodeProjection(w: Writer, p: Projection): void {
  switch (p.kind) {
    case "HUD":
      HudCodec.write(w, p);
      return;
    case "CHARACTER":
      CharacterCodec.write(w, p);
      return;
    case "INVENTORY":
      InventoryCodec.write(w, p);
      return;
    case "ENTITY_PANEL":
      EntityPanelCodec.write(w, p);
      return;
    case "HOVER":
      HoverCodec.write(w, p);
      return;
    case "STATS":
      StatsCodec.write(w, p);
      return;
    case "DEBUG":
      DebugCodec.write(w, p);
      return;
  }
}

/** Writes one UI record (§15.5): the 16-byte header, the body that `body` writes, padding to 4. */
export function writeUiRecord(w: Writer, subId: number, kind: number, status: number, version: number, body: (w: Writer) => void): void {
  const start = w.pos;
  w.u32(subId, 'UiRecord.sub_id');
  w.u16(kind, 'UiRecord.kind');
  w.u16(status, 'UiRecord.status');
  w.u32(version, 'UiRecord.version');
  const lenAt = w.pos;
  w.u32(0, 'UiRecord.len');
  body(w);
  const len = w.pos - lenAt - 4;
  if (len > RECORD_MAX) throw new EncodeError('too_long', 'UiRecord.body');
  w.patchU32(lenAt, len);
  w.pad(start, 4);
}

/** The records of a UI section. */
export function readUiRecords(bytes: Uint8Array, count: number): UiRecord[] {
  const r = new Reader(bytes);
  const out: UiRecord[] = [];
  for (let i = 0; i < count; i++) out.push(UiRecordCodec.read(r));
  r.finish('UI');
  return out;
}
